"use client";
import Link from"next/link";import{useCallback,useEffect,useMemo,useState}from"react";import{Eye,Loader2,MoreHorizontal,Pencil,Search,Trash2,UserPlus,X}from"lucide-react";import{DataActions}from"./data-actions";
type Student={id:string;name:string;admission:string;gender:string;dateOfBirth:string;className:string;section:string;grade:string;rollNumber:string;parent:string;parentPhone:string;parentEmail:string;address:string;admissionDate:string;attendance:number;fee:"Paid"|"Partially Paid"|"Pending"|"Overdue";totalFee:number;paidFee:number;pendingFee:number;status:string;createdAt:string};
const money=(value:number)=>new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",maximumFractionDigits:0}).format(value);
const today=()=>new Date().toISOString().slice(0,10);const initial={name:"",admission:"",gender:"Male",dateOfBirth:"",className:"",section:"",rollNumber:"",parent:"",parentPhone:"",parentEmail:"",address:"",admissionDate:today(),totalFee:"",dueDate:`${new Date().getFullYear()}-12-31`};
export function Students(){const[data,setData]=useState<Student[]>([]),[query,setQuery]=useState(""),[classFilter,setClassFilter]=useState(""),[section,setSection]=useState(""),[fee,setFee]=useState(""),[sort,setSort]=useState("name"),[page,setPage]=useState(1),[open,setOpen]=useState(false),[editing,setEditing]=useState<Student|null>(null),[view,setView]=useState<Student|null>(null),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[error,setError]=useState(""),[success,setSuccess]=useState(""),[academicYear,setAcademicYear]=useState("2026-2027");
 const load=useCallback(async()=>{setLoading(true);try{const r=await fetch("/api/students"),j=await r.json();if(!r.ok)throw new Error(j.error);setData(j.students);setAcademicYear(j.academicYear)}catch(e){setError(e instanceof Error?e.message:"Could not load students.")}finally{setLoading(false)}},[]);useEffect(()=>{void load()},[load]);
 const filtered=useMemo(()=>data.filter(s=>(s.name+s.admission+s.className+s.section+s.parent).toLowerCase().includes(query.toLowerCase())&&(!classFilter||s.className===classFilter)&&(!section||s.section===section)&&(!fee||s.fee===fee)).sort((a,b)=>sort==="attendance"?b.attendance-a.attendance:sort==="pending"?b.pendingFee-a.pendingFee:a.name.localeCompare(b.name)),[data,query,classFilter,section,fee,sort]);const pages=Math.max(1,Math.ceil(filtered.length/10)),rows=filtered.slice((page-1)*10,page*10);useEffect(()=>setPage(1),[query,classFilter,section,fee]);
 async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();setSaving(true);setError("");const f=new FormData(event.currentTarget),body=Object.fromEntries(f.entries());body.totalFee=String(body.totalFee||0);body.academicYear=academicYear;try{const r=await fetch(editing?`/api/students/${editing.id}`:"/api/students",{method:editing?"PUT":"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)}),j=await r.json();if(!r.ok)throw new Error(j.error);await load();setOpen(false);setEditing(null);setSuccess(editing?"Student updated successfully.":"Student added and fee invoice created.")}catch(e){setError(e instanceof Error?e.message:"Could not save student.")}finally{setSaving(false)}}
 async function remove(s:Student){if(!confirm(`Delete ${s.name}? This cannot be undone.`))return;const r=await fetch(`/api/students/${s.id}`,{method:"DELETE"});if(r.ok){setData(x=>x.filter(y=>y.id!==s.id));setSuccess("Student deleted.")}else{const j=await r.json();setError(j.error)}}
 function edit(s:Student){setEditing(s);setOpen(true)}
 const classes=[...new Set(data.map(s=>s.className).filter(Boolean))].sort(),sections=[...new Set(data.map(s=>s.section).filter(Boolean))].sort();
 return <div className="mx-auto max-w-[1500px]"><PageHead eyebrow="People" title="Students" text="Manage enrollment, attendance and fee records from one source of truth."><DataActions type="students" exportQuery={`search=${encodeURIComponent(query)}&class=${encodeURIComponent(classFilter)}&section=${encodeURIComponent(section)}&status=${encodeURIComponent(fee)}`} onDeleted={()=>setData([])}/><button className="btn-primary" onClick={()=>{setEditing(null);setOpen(true)}}><UserPlus className="size-4"/>Add student</button></PageHead>
 {(error||success)&&<div role="alert" className={`mt-5 rounded-xl border p-3 text-sm ${error?"border-red-200 bg-red-50 text-red-700":"border-emerald-200 bg-emerald-50 text-emerald-700"}`}>{error||success}</div>}
 <div className="card mt-7 overflow-hidden"><div className="grid gap-3 border-b p-4 md:grid-cols-5"><label className="flex items-center gap-2 rounded-xl border px-3 md:col-span-2"><Search className="size-4 text-muted"/><input value={query} onChange={e=>setQuery(e.target.value)} className="w-full bg-transparent py-2.5 outline-none" placeholder="Name, admission no., class..."/></label><Select value={classFilter} set={setClassFilter} label="All classes" options={classes}/><Select value={section} set={setSection} label="All sections" options={sections}/><Select value={fee} set={setFee} label="All fee statuses" options={["Paid","Partially Paid","Pending","Overdue"]}/><select className="rounded-xl border bg-panel px-3 py-2 text-sm md:col-start-5" value={sort} onChange={e=>setSort(e.target.value)}><option value="name">Sort: Name</option><option value="attendance">Sort: Attendance</option><option value="pending">Sort: Pending fee</option></select></div>
 {loading?<Loading text="Loading students..."/>:<div className="overflow-x-auto"><table className="w-full whitespace-nowrap text-left text-sm"><thead className="bg-canvas text-xs uppercase tracking-wider text-muted"><tr>{["Student","Admission number","Class","Parent / Phone","Attendance","Total fee","Paid fee","Pending fee","Fee status","Actions"].map(h=><th className="px-4 py-4" key={h}>{h}</th>)}</tr></thead><tbody className="divide-y">{rows.map(s=><tr className="hover:bg-canvas/60" key={s.id}><td className="px-4 py-3"><div className="flex items-center gap-3"><span className="grid size-9 place-items-center rounded-full bg-brand/10 font-bold text-brand">{s.name.split(" ").map(x=>x[0]).slice(0,2).join("")}</span><b>{s.name}</b></div></td><td className="px-4">{s.admission}</td><td className="px-4">{s.className}-{s.section}</td><td className="px-4"><b className="block">{s.parent}</b><span className="text-xs text-muted">{s.parentPhone||"No phone"}</span></td><td className={`px-4 font-bold ${s.attendance<75?"text-red-600":s.attendance<90?"text-orange-600":""}`}>{s.attendance}%</td><td className="px-4">{money(s.totalFee)}</td><td className="px-4 text-emerald-600">{money(s.paidFee)}</td><td className="px-4 font-bold">{money(s.pendingFee)}</td><td className="px-4"><Badge status={s.fee}/></td><td className="px-4"><div className="flex gap-1"><button className="icon-btn" title="View" onClick={()=>setView(s)}><Eye/></button><button className="icon-btn" title="Edit" onClick={()=>edit(s)}><Pencil/></button><Link className="icon-btn" title="View fees and add payment" href={`/dashboard/payments?search=${encodeURIComponent(s.admission)}`}><MoreHorizontal/></Link><button className="icon-btn text-red-600" title="Delete" onClick={()=>void remove(s)}><Trash2/></button></div></td></tr>)}</tbody></table>{rows.length===0&&<Empty title="No students found" text="Try changing your filters or add a new student."/>}</div>}
 <div className="flex items-center justify-between border-t p-4 text-sm text-muted"><span>Showing {rows.length} of {filtered.length} students</span><div className="flex items-center gap-2"><button className="btn-secondary !px-3 !py-1.5" disabled={page===1} onClick={()=>setPage(p=>p-1)}>Previous</button><span>{page} / {pages}</span><button className="btn-secondary !px-3 !py-1.5" disabled={page===pages} onClick={()=>setPage(p=>p+1)}>Next</button></div></div></div>
 {open&&<StudentModal student={editing} initialData={initial} onClose={()=>{setOpen(false);setEditing(null)}} onSubmit={submit} saving={saving}/>} {view&&<StudentView student={view} onClose={()=>setView(null)}/>}</div>}
function PageHead({eyebrow,title,text,children}:{eyebrow:string;title:string;text:string;children:React.ReactNode}){return <div className="flex flex-col items-start justify-between gap-4 xl:flex-row xl:items-end"><div><p className="label">{eyebrow}</p><h1 className="mt-2 text-3xl font-black">{title}</h1><p className="mt-1 text-muted">{text}</p></div><div className="flex flex-wrap gap-2">{children}</div></div>}
function Select({value,set,label,options}:{value:string;set:(v:string)=>void;label:string;options:string[]}){return <select className="rounded-xl border bg-panel px-3 py-2.5 text-sm" value={value} onChange={e=>set(e.target.value)}><option value="">{label}</option>{options.map(x=><option key={x}>{x}</option>)}</select>}
function Badge({status}:{status:string}){return <span className={`rounded-full px-2.5 py-1 text-xs font-bold ${status==="Paid"?"bg-emerald-100 text-emerald-700":status==="Overdue"?"bg-red-100 text-red-700":status==="Partially Paid"?"bg-blue-100 text-blue-700":"bg-orange-100 text-orange-700"}`}>{status}</span>}
function Loading({text}:{text:string}){return <div className="grid min-h-72 place-items-center text-sm text-muted"><div className="text-center"><Loader2 className="mx-auto mb-3 animate-spin text-brand"/>{text}</div></div>}
function Empty({title,text}:{title:string;text:string}){return <div className="p-12 text-center"><b>{title}</b><p className="mt-1 text-sm text-muted">{text}</p></div>}
function StudentModal({student,initialData,onClose,onSubmit,saving}:{student:Student|null;initialData:typeof initial;onClose:()=>void;onSubmit:(e:React.FormEvent<HTMLFormElement>)=>void;saving:boolean}){const d=student??initialData;return <div className="fixed inset-0 z-[70] grid place-items-center bg-black/45 p-4"><form onSubmit={onSubmit} className="card max-h-[92vh] w-full max-w-3xl overflow-y-auto p-6 sm:p-8"><div className="flex justify-between"><div><h2 className="text-xl font-bold">{student?"Edit student":"Add student"}</h2><p className="text-sm text-muted">Enrollment and annual fee information.</p></div><button type="button" onClick={onClose}><X/></button></div><div className="mt-6 grid gap-4 sm:grid-cols-2"><Field name="name" label="Student name" value={d.name}/><Field name="admission" label="Admission number" value={d.admission}/><Field name="gender" label="Gender" select={["Male","Female","Other"]} value={d.gender}/><Field name="dateOfBirth" label="Date of birth" type="date" value={d.dateOfBirth}/><Field name="className" label="Class" value={d.className}/><Field name="section" label="Section" value={d.section}/><Field name="rollNumber" label="Roll number" value={d.rollNumber}/><Field name="admissionDate" label="Admission date" type="date" value={d.admissionDate}/><Field name="parent" label="Parent / guardian" value={d.parent}/><Field name="parentPhone" label="Parent phone" value={d.parentPhone}/><Field name="parentEmail" label="Parent email" type="email" value={d.parentEmail}/><Field name="totalFee" label="Total annual fee" type="number" value={String(d.totalFee)}/>{!student&&<Field name="dueDate" label="Fee due date" type="date" value={initialData.dueDate}/>}<label className="text-sm font-bold sm:col-span-2">Address<textarea name="address" defaultValue={d.address} className="mt-2 min-h-20 w-full rounded-xl border bg-canvas px-4 py-3 font-normal outline-none focus:ring-2 focus:ring-brand"/></label></div><div className="mt-7 flex justify-end gap-2"><button type="button" className="btn-secondary" onClick={onClose}>Cancel</button><button disabled={saving} className="btn-primary">{saving&&<Loader2 className="size-4 animate-spin"/>}{saving?"Saving student...":"Save student"}</button></div></form></div>}
function Field({name,label,value,type="text",select,disabled=false}:{name:string;label:string;value:string;type?:string;select?:string[];disabled?:boolean}){return <label className="text-sm font-bold">{label}{select?<select name={name} defaultValue={value} className="mt-2 w-full rounded-xl border bg-canvas px-4 py-3 font-normal">{select.map(x=><option key={x}>{x}</option>)}</select>:<input required={!['rollNumber','parentPhone','parentEmail'].includes(name)} name={name} type={type} defaultValue={value} disabled={disabled} className="mt-2 w-full rounded-xl border bg-canvas px-4 py-3 font-normal outline-none focus:ring-2 focus:ring-brand disabled:opacity-60"/>}</label>}
function StudentView({student:s,onClose}:{student:Student;onClose:()=>void}){return <div className="fixed inset-0 z-[70] grid place-items-center bg-black/45 p-4"><div className="card w-full max-w-xl p-7"><div className="flex justify-between"><div><p className="label">Student profile</p><h2 className="mt-2 text-2xl font-black">{s.name}</h2><p className="text-muted">{s.admission} · {s.className}-{s.section}</p></div><button onClick={onClose}><X/></button></div><div className="mt-6 grid grid-cols-2 gap-3 rounded-2xl bg-canvas p-4 text-sm"><div><span className="text-muted">Attendance</span><b className="block text-xl">{s.attendance}%</b></div><div><span className="text-muted">Fee status</span><b className="block text-xl">{s.fee}</b></div><div><span className="text-muted">Total fee</span><b className="block">{money(s.totalFee)}</b></div><div><span className="text-muted">Paid / pending</span><b className="block">{money(s.paidFee)} / {money(s.pendingFee)}</b></div></div><div className="mt-5 text-sm"><b>Parent / guardian</b><p className="text-muted">{s.parent} · {s.parentPhone||"No phone"}</p><p className="text-muted">{s.parentEmail||"No email"}</p></div><Link className="btn-primary mt-6 w-full" href={`/dashboard/payment-history?studentId=${s.id}`}>View payment history</Link></div></div>}

