"use client";import{useEffect,useMemo,useState}from"react";import{Loader2,Pencil,Plus,Search,Trash2,X}from"lucide-react";import{DataActions}from"./data-actions";
type Teacher={id:string;name:string;employeeId:string;email:string;phone:string;department:string;subject:string;classes:string;joiningDate:string;salary:number;status:string;createdAt:string};const empty={name:"",employeeId:"",email:"",phone:"",department:"",subject:"",classes:"",joiningDate:new Date().toISOString().slice(0,10),salary:0,status:"Active"};
export function Teachers(){const[data,setData]=useState<Teacher[]>([]),[query,setQuery]=useState(""),[open,setOpen]=useState(false),[edit,setEdit]=useState<Teacher|null>(null),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[message,setMessage]=useState("");async function load(){setLoading(true);const r=await fetch("/api/teachers"),j=await r.json();if(r.ok)setData(j.teachers);else setMessage(j.error);setLoading(false)}useEffect(()=>{void load()},[]);const rows=useMemo(()=>data.filter(t=>(t.name+t.employeeId+t.subject+t.department).toLowerCase().includes(query.toLowerCase())),[data,query]);async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setSaving(true);const body=Object.fromEntries(new FormData(e.currentTarget));const r=await fetch(edit?`/api/teachers/${edit.id}`:"/api/teachers",{method:edit?"PUT":"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)}),j=await r.json();setSaving(false);if(!r.ok)return setMessage(j.error);setOpen(false);setEdit(null);setMessage(edit?"Teacher updated.":"Teacher added.");await load()}async function remove(t:Teacher){if(!confirm(`Delete ${t.name}?`))return;const r=await fetch(`/api/teachers/${t.id}`,{method:"DELETE"});if(r.ok)setData(x=>x.filter(y=>y.id!==t.id))}
return <div className="mx-auto max-w-7xl"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="label">People</p><h1 className="mt-2 text-3xl font-black">Teachers</h1><p className="mt-1 text-muted">Manage faculty profiles, subjects and assigned classes.</p></div><div className="flex flex-wrap gap-2"><DataActions type="teachers" onDeleted={()=>setData([])}/><button className="btn-primary" onClick={()=>{setEdit(null);setOpen(true)}}><Plus className="size-4"/>Add teacher</button></div></div>{message&&<p className="mt-5 rounded-xl border bg-panel p-3 text-sm">{message}</p>}<section className="mt-7 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[["Total teachers",data.length],["Active",data.filter(x=>x.status==="Active").length],["On leave",data.filter(x=>x.status==="On Leave").length],["Departments",new Set(data.map(x=>x.department)).size]].map(([k,v])=><div className="card p-5" key={k}><p className="text-sm text-muted">{k}</p><b className="mt-2 block text-3xl">{v}</b></div>)}</section><div className="card mt-5 overflow-hidden"><div className="border-b p-4"><label className="flex max-w-md items-center gap-2 rounded-xl border px-3"><Search className="size-4"/><input className="w-full bg-transparent py-2.5 outline-none" placeholder="Name, employee ID, subject..." value={query} onChange={e=>setQuery(e.target.value)}/></label></div>{loading?<div className="grid min-h-64 place-items-center"><Loader2 className="animate-spin text-brand"/></div>:<div className="overflow-x-auto"><table className="w-full whitespace-nowrap text-left text-sm"><thead className="bg-canvas text-xs uppercase text-muted"><tr>{["Teacher","Employee ID","Department","Primary subject","Assigned classes","Phone / Email","Joining date","Status","Actions"].map(x=><th className="px-4 py-4" key={x}>{x}</th>)}</tr></thead><tbody className="divide-y">{rows.map(t=><tr key={t.id}><td className="px-4 py-4 font-bold">{t.name}</td><td className="px-4">{t.employeeId}</td><td className="px-4">{t.department}</td><td className="px-4">{t.subject}</td><td className="px-4">{t.classes||"—"}</td><td className="px-4"><b className="block">{t.phone}</b><span className="text-xs text-muted">{t.email}</span></td><td className="px-4">{t.joiningDate}</td><td className="px-4"><span className="rounded-full bg-emerald-100 px-2 py-1 text-xs font-bold text-emerald-700">{t.status}</span></td><td className="px-4"><button className="icon-btn" onClick={()=>{setEdit(t);setOpen(true)}}><Pencil/></button><button className="icon-btn text-red-600" onClick={()=>void remove(t)}><Trash2/></button></td></tr>)}</tbody></table>{!rows.length&&<p className="p-12 text-center text-muted">No teachers found. Add your first teacher to get started.</p>}</div>}</div>{open&&<Modal teacher={edit} saving={saving} close={()=>setOpen(false)} submit={submit}/>}</div>}
function Modal({teacher,saving,close,submit}:{teacher:Teacher|null;saving:boolean;close:()=>void;submit:(e:React.FormEvent<HTMLFormElement>)=>void}){const d=teacher??empty;const fields:[keyof typeof empty,string,string?][]=[["name","Teacher name"],["employeeId","Employee ID"],["department","Department"],["subject","Primary subject"],["classes","Assigned classes"],["phone","Phone","tel"],["email","Email","email"],["joiningDate","Joining date","date"],["salary","Salary","number"]];return <div className="fixed inset-0 z-[70] grid place-items-center bg-black/45 p-4"><form onSubmit={submit} className="card max-h-[90vh] w-full max-w-2xl overflow-y-auto p-7"><div className="flex justify-between"><h2 className="text-xl font-bold">{teacher?"Edit teacher":"Add teacher"}</h2><button type="button" onClick={close}><X/></button></div><div className="mt-6 grid gap-4 sm:grid-cols-2">{fields.map(([key,label,type])=><label className="text-sm font-bold" key={key}>{label}<input required={!['classes','email'].includes(key)} name={key} type={type||"text"} defaultValue={String(d[key])} className="mt-2 w-full rounded-xl border bg-canvas px-4 py-3 font-normal"/></label>)}<label className="text-sm font-bold">Status<select name="status" defaultValue={d.status} className="mt-2 w-full rounded-xl border bg-canvas px-4 py-3 font-normal"><option>Active</option><option>Inactive</option><option>On Leave</option></select></label></div><div className="mt-6 flex justify-end gap-2"><button type="button" className="btn-secondary" onClick={close}>Cancel</button><button className="btn-primary" disabled={saving}>{saving&&<Loader2 className="size-4 animate-spin"/>}{saving?"Saving teacher...":"Save teacher"}</button></div></form></div>}
